public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    int maxLength = 0;

    for (int length = 1; length <= strings.get(0).length(); length++) {
        boolean found = true;
        for (int i = 0; i <= strings.get(0).length() - length; i++) {
            String substring = strings.get(0).substring(i, i + length);
            String reversedSubstring = new StringBuilder(substring).reverse().toString();
            for (String str : strings) {
                if (!str.contains(substring) && !str.contains(reversedSubstring)) {
                    found = false;
                    break;
                }
            }
            if (found) {
                maxLength = length;
            }
        }
    }

    return maxLength;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    int maxLength = 0;

    for (int i = 0; i < strings.size(); i++) {
        String str = strings.get(i);
        for (int j = 0; j < str.length(); j++) {
            for (int k = j + 1; k <= str.length(); k++) {
                String substring = str.substring(j, k);
                String reversedSubstring = new StringBuilder(substring).reverse().toString();

                boolean isCommon = true;
                for (String other : strings) {
                    if (!other.contains(substring) && !other.contains(reversedSubstring)) {
                        isCommon = false;
                        break;
                    }
                }

                if (isCommon) {
                    maxLength = Math.max(maxLength, substring.length());
                }
            }
        }
    }

    return maxLength;
}

