    boolean[][] visited = new boolean[n][n];
    return canTravelHelper(start[0], start[1], end[0], end[1], paths, visited) ? "can be travelled" : "cannot be travelled";
}

private static boolean canTravelHelper(int x, int y, int endX, int endY, int[][] paths, boolean[][] visited) {
    if (x == endX && y == endY) {
        return true;
    }
    visited[x][y] = true;

    for (int[] path : paths) {
        if (path[0] == x && path[1] == y && !visited[path[2]][path[3]]) {
            if (canTravelHelper(path[2], path[3], endX, endY, paths, visited)) {
                return true;
            }
        } else if (path[2] == x && path[3] == y && !visited[path[0]][path[1]]) {
            if (canTravelHelper(path[0], path[1], endX, endY, paths, visited)) {
                return true;
            }
        }
    }
    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);
    visited[start[0]][start[1]] = true;

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        for (int[] path : paths) {
            int newX = current[0] + path[0];
            int newY = current[1] + path[1];
            if (newX >= 0 && newX < n && newY >= 0 && newY < n && !visited[newX][newY]) {
                visited[newX][newY] = true;
                queue.offer(new int[]{newX, newY});
            }
        }
    }

    return "cannot be travelled";
}

