private static boolean dfs(int x, int y, int ex, int ey, boolean[][] visited, int[][] paths) {
    if (x < 0 || y < 0 || x >= visited.length || y >= visited.length || visited[x][y]) {
        return false;
    }

    if (x == ex && y == ey) {
        return true;
    }

    visited[x][y] = true;

    for (int[] path : paths) {
        int nx = x + path[0];
        int ny = y + path[1];
        if (dfs(nx, ny, ex, ey, visited, paths)) {
            return true;
        }
    }

    return false;
}

