private static boolean canTravel(int n, int startX, int startY, int endX, int endY, int[][] paths, boolean[][] visited) {
    if (startX == endX && startY == endY) {
        return true;
    }

    if (startX < 0 || startX >= n || startY < 0 || startY >= n || visited[startX][startY]) {
        return false;
    }

    visited[startX][startY] = true;

    for (int[] path : paths) {
        if ((path[0] == startX && path[1] == startY) || (path[1] == startX && path[0] == startY)) {
            if (canTravel(n, path[1], path[0], endX, endY, paths, visited)) {
                return true;
            }
        }
    }

    visited[startX][startY] = false;
    return false;
}

