public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    int n = nums.length;
    boolean[][] dp = new boolean[n / 2 + 1][sum + 1];
    dp[0][0] = true;

    for (int num : nums) {
        for (int i = n / 2; i >= 1; i--) {
            for (int j = sum; j >= num; j--) {
                dp[i][j] = dp[i][j] || dp[i - 1][j - num];
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0 && dp[i][sum * i / n]) {
            return true;
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    int n = nums.length;
    boolean[][][] dp = new boolean[n + 1][n / 2 + 1][sum + 1];
    dp[0][0][0] = true;

    for (int i = 1; i <= n; i++) {
        int num = nums[i - 1];
        for (int j = Math.min(i, n / 2); j > 0; j--) {
            for (int k = 0; k <= sum; k++) {
                if (dp[i - 1][j][k]) {
                    dp[i][j][k] = true;
                    if (k + num <= sum) {
                        dp[i][j + 1][k + num] = true;
                    }
                }
            }
        }
    }

    for (int j = 1; j <= n / 2; j++) {
        for (int k = 0; k <= sum; k++) {
            if (dp[n][j][k] && k * n == sum * j) {
                return true;
            }
        }
    }

    return false;
}

