public int minInsertions(String s) {
    int open = 0; // Tracks the number of unmatched '('
    int insertions = 0; // Tracks the number of insertions needed

    for (char c : s.toCharArray()) {
        if (c == '(') {
            open++;
        } else if (c == ')') {
            if (open > 0) {
                open--; // Match the ')'
            } else {
                insertions++; // Need to insert a '(' to match this ')'
            }
        }
    }

    // Each unmatched '(' needs a ')' to balance
    insertions += open;

    return insertions;
}

public int minInsertions(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }

    int left = 0;
    int right = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (right % 2 != 0) {
                left++;
                right--;
            }
            right += 2;
        } else if (c == ')') {
            right--;
            if (right < 0) {
                left++;
                right = 1;
            }
        }
    }

    return left + right;
}

public int minInsertions(String s) {
    int open = 0; // To count the number of open parentheses needed
    int close = 0; // To count the number of close parentheses needed
    int insertions = 0; // To count the total number of insertions

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            if (close > 0) {
                // We have an unmatched ')', need to insert a '(' before it
                insertions += close;
                open += close;
                close = 0;
            }
            open++;
        } else if (s.charAt(i) == ')') {
            if (open > 0) {
                open--; // Match the current ')' with a '('
            } else {
                close++; // We need to insert a '(' to match this ')'
            }
        }
    }

    // After processing all characters, we need to insert remaining pairs
    insertions += open + close;

    return insertions;
}

