public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    int a = 1, b = 1;
    while (b <= k) {
        int temp = b;
        b = a + b;
        a = temp;
    }

    int count = 0;
    while (k > 0) {
        if (a <= k) {
            k -= a;
            count++;
        }
        int temp = a;
        a = b - a;
        b = temp;
    }

    return count;
}

