public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    int i = 0;
    while (i < n) {
        int remaining = n - i - 1;
        int minSum = remaining * 26;
        if (k - minSum <= 26) {
            result.append((char) ('a' + (k - minSum - 1)));
            k -= (k - minSum);
        } else {
            result.append('a');
            k -= 1;
        }
        i++;
    }
    return result.toString();
}

public String getSmallestString(int n, int k) {
    if (n <= 0 || k <= 0 || k < n || k > 26 * n) {
        throw new IllegalArgumentException("Invalid input");
    }

    char[] result = new char[n];
    int valueLeft = k - n; // Each 'a' contributes 1 to the value

    for (int i = n - 1; i >= 0; i--) {
        if (valueLeft >= 25) {
            result[i] = 'z';
            valueLeft -= 25;
        } else {
            result[i] = (char) ('a' + valueLeft);
            valueLeft = 0;
        }
    }

    return new String(result);
}

