        }
    }
    Collections.sort(result);
    return result;
}

private static void bfs(List<Integer> result, int num, int low, int high) {
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(num);
    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current > high) {
            continue;
        }
        if (current >= low) {
            result.add(current);
        }
        int lastDigit = current % 10;
        int nextNum1 = current * 10 + (lastDigit - 1);
        int nextNum2 = current * 10 + (lastDigit + 1);
        if (lastDigit > 0 && nextNum1 <= high) {
            queue.offer(nextNum1);
        }
        if (lastDigit < 9 && nextNum2 <= high) {
            queue.offer(nextNum2);
        }
    }
}

