public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    char[][] pairs = {{'0', '0'}, {'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'}};
    helper(result, new char[n], 0, n - 1, pairs);
    return result;
}

private static void helper(List<String> result, char[] chars, int left, int right, char[][] pairs) {
    if (left > right) {
        result.add(new String(chars));
        return;
    }
    for (char[] pair : pairs) {
        if (left == right && (pair[0] == '6' || pair[0] == '9')) {
            continue;
        }
        if (left != right && left == 0 && pair[0] == '0') {
            continue;
        }
        chars[left] = pair[0];
        chars[right] = pair[1];
        helper(result, chars, left + 1, right - 1, pairs);
    }
}

