private static List<String> helper(int currentLength, int targetLength, char[] chars, List<String> result) {
    if (currentLength == 0) {
        result.add(new String(chars));
        return result;
    }
    if (currentLength == 1) {
        chars[targetLength / 2] = '0';
        result.add(new String(chars));
        chars[targetLength / 2] = '1';
        result.add(new String(chars));
        chars[targetLength / 2] = '8';
        result.add(new String(chars));
        return result;
    }
    int[] pairs = {0, 0, 1, 1, 8, 8, 6, 9, 9, 6};
    for (int i = 0; i < pairs.length; i += 2) {
        if (currentLength == targetLength && pairs[i] == 0) {
            continue;
        }
        chars[targetLength - currentLength] = (char) ('0' + pairs[i]);
        chars[currentLength - 1 + targetLength - currentLength] = (char) ('0' + pairs[i + 1]);
        helper(currentLength - 2, targetLength, chars, result);
    }
    return result;
}

public static List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("The length of the center symmetric numbers must be a positive integer.");
    }

    List<String> result = new ArrayList<>();
    if (n == 1) {
        result.add("0");
        result.add("1");
        result.add("8");
        return result;
    }

    String[] pairs = {"00", "11", "69", "88", "96"};
    List<String> inner = centerSymmetricNumbers(n - 2);

    for (String middle : inner) {
        for (int i = 1; i < pairs.length; i++) { // Skip "00" for non-boundary positions
            result.add(pairs[i].charAt(0) + middle + pairs[i].charAt(1));
        }
    }

    if (n % 2 == 0) {
        for (String middle : inner) {
            result.add("00" + middle + "00");
        }
    } else {
        for (String middle : inner) {
