public static int calculateUniqueSum(int[] nums) {
    if (nums == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }

    int sum = 0;
    java.util.HashSet<Integer> seenOnce = new java.util.HashSet<>();
    java.util.HashSet<Integer> seenMoreThanOnce = new java.util.HashSet<>();

    for (int num : nums) {
        if (seenMoreThanOnce.contains(num)) {
            continue;
        } else if (seenOnce.contains(num)) {
            seenOnce.remove(num);
            seenMoreThanOnce.add(num);
        } else {
            seenOnce.add(num);
        }
    }

    for (int num : seenOnce) {
        sum += num;
    }

    return sum;
}

